#include <bits/stdc++.h>
using namespace std;
class Solution {public:int totalSteps(vector<int>& nums){vector<pair<int,int>> st;int ans=0;for(int x:nums){int rounds=0;while(!st.empty()&&st.back().first<=x){rounds=max(rounds,st.back().second);st.pop_back();}rounds=st.empty()?0:rounds+1;ans=max(ans,rounds);st.push_back({x,rounds});}return ans;}};
